/**
 * Builds the browser-only distribution.
 *
 * The generated files at the project root are the game itself:
 *   index.html + styles.css + game.js
 * game.js is a classic (non-module) IIFE bundle, so the game runs by simply
 * opening index.html from disk. No local web server or Node.js is required.
 *
 * Source files live in src/ and the development page is dev.html.
 */
import { access, cp, readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'vite';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const DIST = path.join(ROOT, 'dist');

process.chdir(ROOT);

console.log('[build] bundling Three.js, PeerJS and the game source…');
await build({
  root: ROOT,
  configFile: path.join(ROOT, 'vite.config.js'),
  logLevel: 'warn',
});

for (const file of ['game.js', 'styles.css']) {
  await access(path.join(DIST, file));
}

let html = await readFile(path.join(ROOT, 'dev.html'), 'utf8');
const devScript = /\s*<script\s+type="module"\s+src="\/src\/main\.js"><\/script>/;

if (!devScript.test(html)) {
  throw new Error('Could not find the development module script in dev.html');
}

html = html
  .replace(devScript, '')
  .replace(
    '</head>',
    '  <link rel="stylesheet" href="./styles.css" />\n'
      + '  <script defer src="./game.js"></script>\n'
      + '</head>',
  )
  .replace(
    '<!DOCTYPE html>',
    '<!DOCTYPE html>\n<!-- Generated by `npm run build`. Edit dev.html / src/ and rebuild. -->',
  );

await Promise.all([
  writeFile(path.join(DIST, 'index.html'), html),
  writeFile(path.join(ROOT, 'index.html'), html),
  cp(path.join(DIST, 'game.js'), path.join(ROOT, 'game.js')),
  cp(path.join(DIST, 'styles.css'), path.join(ROOT, 'styles.css')),
]);

console.log('[build] ready: index.html, styles.css, game.js');
console.log('[build] open index.html directly in Chrome / Edge, or publish the 3 files as static hosting.');
